parameters.jsCode:
// ==================================================
// Investigation Step Expander
//
// Converts one canonical investigation plan into
// one n8n item per investigation step.
//
// The authoritative plan context required by the
// downstream aggregator is propagated with every
// expanded tool request.
// ==================================================

const plan = $json;


// --------------------------------------------------
// 1. Validate plan
// --------------------------------------------------

if (
  typeof plan !== "object" ||
  plan === null ||
  Array.isArray(plan)
) {
  throw new Error(
    "Investigation Step Expander received an invalid plan"
  );
}


if (
  typeof plan.alert_id !== "string" ||
  plan.alert_id.trim() === ""
) {
  throw new Error(
    "Investigation Step Expander requires alert_id"
  );
}


if (
  !Array.isArray(
    plan.investigation_steps
  )
) {
  throw new Error(
    "Investigation Step Expander requires investigation_steps"
  );
}


if (
  plan.investigation_steps.length === 0
) {
  throw new Error(
    "Investigation Step Expander received an empty investigation plan"
  );
}


const requestedSteps =
  plan.investigation_steps.length;


// --------------------------------------------------
// 2. Expand steps
// --------------------------------------------------

const items = [];

for (
  let index = 0;
  index < plan.investigation_steps.length;
  index++
) {

  const step =
    plan.investigation_steps[index];


  if (
    typeof step !== "object" ||
    step === null ||
    Array.isArray(step)
  ) {
    throw new Error(
      `investigation_steps[${index}] must be an object`
    );
  }


  if (
    typeof step.step_id !== "string" ||
    step.step_id.trim() === ""
  ) {
    throw new Error(
      `investigation_steps[${index}].step_id is required`
    );
  }


  if (
    typeof step.tool !== "string" ||
    step.tool.trim() === ""
  ) {
    throw new Error(
      `investigation_steps[${index}].tool is required`
    );
  }


  if (
    typeof step.parameters !== "object" ||
    step.parameters === null ||
    Array.isArray(step.parameters)
  ) {
    throw new Error(
      `investigation_steps[${index}].parameters must be an object`
    );
  }


  // ----------------------------------------------
  // Canonical tool request
  //
  // plan_context is propagated so downstream
  // aggregation does not depend on a specific
  // upstream node name.
  // ----------------------------------------------

  items.push({
    json: {
      request_version:
        "1.0",

      alert_id:
        plan.alert_id,

      step_id:
        step.step_id,

      tool:
        step.tool,

      parameters:
        step.parameters,

      context: {
        priority:
          step.priority || null,

        purpose:
          step.purpose || null,

        evidence_target:
          step.evidence_target || null
      },

      plan_context: {
        plan_version:
          plan.plan_version || "1.0",

        iteration_number:
          Number.isInteger(plan.iteration_number)
            ? plan.iteration_number
            : null,

        objective:
          typeof plan.objective === "string"
            ? plan.objective
            : "",

        requested_steps:
          requestedSteps
      }
    }
  });
}


// --------------------------------------------------
// 3. Return one n8n item per investigation step
// --------------------------------------------------

return items;

// ==================================================
// Investigation Evidence Aggregator
//
// Aggregates canonical tool execution results into
// one Canonical Investigation Evidence Bundle.
//
// This version does not depend on a specific
// upstream node name. Required investigation-plan
// context must arrive with the tool result context.
// ==================================================


// --------------------------------------------------
// 1. Read all tool execution results
// --------------------------------------------------

const items =
  $input.all();


if (
  !Array.isArray(items) ||
  items.length === 0
) {
  throw new Error(
    "Investigation Evidence Aggregator received no tool results"
  );
}


const results =
  items.map(
    item => item.json
  );


// --------------------------------------------------
// 2. Recover authoritative plan context
// --------------------------------------------------

let alertId = null;
let investigationObjective = "";
let requestedSteps = null;
let iterationNumber = null;


// All results must refer to the same alert and
// compatible propagated plan context.

for (
  let index = 0;
  index < results.length;
  index++
) {

  const result =
    results[index];


  if (
    !result ||
    typeof result !== "object" ||
    Array.isArray(result)
  ) {
    throw new Error(
      `Tool result at execution ${index + 1} is not a valid object`
    );
  }


  if (
    typeof result.alert_id !== "string" ||
    result.alert_id.trim() === ""
  ) {
    throw new Error(
      `Tool result at execution ${index + 1} does not contain alert_id`
    );
  }


  if (
    alertId === null
  ) {

    alertId =
      result.alert_id;

  } else if (
    alertId !== result.alert_id
  ) {

    throw new Error(
      "Investigation Evidence Aggregator received results from different alert_ids"
    );
  }


  const planContext =
    (
      result.plan_context &&
      typeof result.plan_context === "object" &&
      !Array.isArray(result.plan_context)
    )
      ? result.plan_context
      : null;


  if (planContext) {

    if (
      typeof planContext.objective === "string" &&
      investigationObjective === ""
    ) {
      investigationObjective =
        planContext.objective;
    }


    if (
      Number.isInteger(
        planContext.requested_steps
      )
    ) {

      if (
        requestedSteps === null
      ) {

        requestedSteps =
          planContext.requested_steps;

      } else if (
        requestedSteps !==
          planContext.requested_steps
      ) {

        throw new Error(
          "Investigation Evidence Aggregator received inconsistent requested_steps values"
        );
      }
    }


    if (
      Number.isInteger(
        planContext.iteration_number
      )
    ) {

      if (
        iterationNumber === null
      ) {

        iterationNumber =
          planContext.iteration_number;

      } else if (
        iterationNumber !==
          planContext.iteration_number
      ) {

        throw new Error(
          "Investigation Evidence Aggregator received inconsistent iteration_number values"
        );
      }
    }
  }
}


// --------------------------------------------------
// 3. Fallback requested step count
// --------------------------------------------------

if (
  requestedSteps === null
) {
  requestedSteps =
    results.length;
}


// --------------------------------------------------
// 4. Counters
// --------------------------------------------------

let successfulTools = 0;
let partialTools = 0;
let failedTools = 0;
let rejectedTools = 0;
let totalEvidenceItems = 0;


// --------------------------------------------------
// 5. Normalize tool executions
// --------------------------------------------------

const toolExecutions =
  results.map(
    (result, index) => {

      const tool =
        result.tool;


      if (
        typeof tool !== "string" ||
        tool.trim() === ""
      ) {
        throw new Error(
          `Tool result at execution ${index + 1} does not contain a valid tool`
        );
      }


      const status =
        result.status;


      const validStatuses = [
        "success",
        "partial",
        "error",
        "rejected"
      ];


      if (
        !validStatuses.includes(status)
      ) {
        throw new Error(
          `Tool result '${tool}' contains invalid status '${status}'`
        );
      }


      let evidence = [];


      if (
        status === "success" ||
        status === "partial"
      ) {

        if (
          !Array.isArray(
            result.evidence
          )
        ) {
          throw new Error(
            `Tool result '${tool}' does not contain an evidence array`
          );
        }


        evidence =
          result.evidence;

      } else {

        evidence =
          Array.isArray(
            result.evidence
          )
            ? result.evidence
            : [];
      }


      const resultCount =
        Number.isInteger(
          result.result_count
        )
          ? result.result_count
          : evidence.length;


      if (
        resultCount !==
        evidence.length
      ) {
        throw new Error(
          `Tool result '${tool}' result_count does not match evidence.length`
        );
      }


      const toolVersion =
        (
          typeof result.version === "string" &&
          result.version.trim() !== ""
        )
          ? result.version
          : (
              typeof result.tool_version === "string" &&
              result.tool_version.trim() !== ""
            )
              ? result.tool_version
              : null;


      if (
        status === "success"
      ) {
        successfulTools++;
      }


      if (
        status === "partial"
      ) {
        partialTools++;
      }


      if (
        status === "error"
      ) {
        failedTools++;
      }


      if (
        status === "rejected"
      ) {
        rejectedTools++;
      }


      totalEvidenceItems +=
        evidence.length;


      return {

        execution_index:
          index + 1,

        step_id:
          result.step_id || null,

        tool,

        tool_version:
          toolVersion,

        status,

        query:
          (
            result.query &&
            typeof result.query === "object" &&
            !Array.isArray(result.query)
          )
            ? result.query
            : {},

        result_count:
          resultCount,

        evidence,

        error:
          result.error ?? null
      };
    }
  );


// --------------------------------------------------
// 6. Determine bundle status
// --------------------------------------------------

let bundleStatus =
  "success";


if (
  failedTools > 0 ||
  rejectedTools > 0
) {

  bundleStatus =
    successfulTools > 0 ||
    partialTools > 0
      ? "partial"
      : "error";

} else if (
  partialTools > 0
) {

  bundleStatus =
    "partial";
}


// --------------------------------------------------
// 7. Build Canonical Investigation Evidence Bundle
// --------------------------------------------------

return [
  {
    json: {

      evidence_bundle_version:
        "1.0",

      alert_id:
        alertId,

      iteration_number:
        iterationNumber,

      investigation_objective:
        investigationObjective,

      status:
        bundleStatus,

      execution_summary: {

        requested_steps:
          requestedSteps,

        executed_tools:
          toolExecutions.length,

        successful_tools:
          successfulTools,

        partial_tools:
          partialTools,

        failed_tools:
          failedTools,

        rejected_tools:
          rejectedTools,

        total_evidence_items:
          totalEvidenceItems
      },

      tool_executions:
        toolExecutions
    }
  }
];

